#[must_use]
pub(crate) fn credentials(request: &impl runtime::Secured) -> Vec<Credential<'_>> {
    request
        .credentials()
        .iter()
        .filter_map(|(scheme, value)| match scheme.name() {
            "basicAuth" => {
                let (user, password) = value
                    .split_once(':')
                    .unwrap_or((value.as_str(), ""));
                Some(Credential::BasicAuth {
                    user,
                    password,
                })
            }
            _ => None,
        })
        .collect()
}
